  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "动机、四种路径、访问模式、范围版本、存储代次及地址和内容资格均已定义。内容写入与存储复用使用不同身份，能够解释部分改写与迟到完成。",
      "evidence": [
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "部分改写需要范围版本图 ν(b)：它记录字节 b 最近一次成功写入的内容序号。"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "首次 OVERWRITE 可以没有 valid，但必须具备 addr；READ 同时需要两者。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "区分平台能力、准备生效、内容可见性和最后使用；映射原子限制、UVM 支持级别及图池两种非并发共享条件与所供原文相符。完成后准入明确属于本章保守方案，未被误写为 UVM 预取的普遍限制。",
      "evidence": [
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "所有内部复制的源和目的也必须满足各自的地址资格，不能只检查最终消费者。"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "合法 UVM 运行时可以按其契约在预取期间继续服务访问；应用需要遵守支持级别和读写同步，不能把本章的软件锁误作 CUDA 禁止预取期间访问的规定。"
        }
      ]
    },
    "algorithm": {
      "assessment": "partial",
      "reason": "A03 的安全性缺口已关闭：共享 pending、真实 backing 范围冲突、消费者检查全部相关移动及原子登记均已展开，反序完成轨迹也成立。但已建立恢复任务因冲突进入 WAIT 后，缺少明确的重新准入转换；检查代码通过外部再次调用 start_copy 推进，尚未验证正文循环能够完成这一转换，见 A04。",
      "evidence": [
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "检查并登记操作的全部源、目标和辅助范围是同一状态事务，不能逐个取得后等待另一个范围。"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "若存在相同 key 的 WAIT/ACTIVE 任务：\n            将 parent 加入订阅者，保存同一完成票据，不重复提交"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "冲突时任务保持 WAIT；不能绕过其他父访问的已提交物理读者或写者"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "同轨迹字节账、交点推导和算例量纲正确；迁移按实际页事件累计，映射数据事务与页覆盖分开。计算共同项、准备、同步、物理容量及共享恢复的通信和管理成本均有条件说明。",
      "evidence": [
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "T_copy≈D/B_l+R·x·D/B_d+E_copy，"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "Q_mig=Σ_{e∈E}s_e=Σ_p m_p·g_p。"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "共享恢复任务按实际启动的任务计 Q_c，不能按订阅消费者数重复收费。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "重复读取、稀疏访问、仅写输出、交替改写、页大小、容量及平台变化均连接到须保留的正确性关系和需重算的成本；共享恢复的等待与独立目标容量也进入选择。",
      "evidence": [
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "局部复制、缓存改变、写后补复制、方向不同的链路带宽或 β≠1 都应回到 Q_c、Q_d、Q_remote 原式，不沿用这个交点。"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "共享 pending 可以减少重复传输，却可能让多个消费者共同等待一个较慢任务，应与拆分范围或独立目标的额外容量比较。"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "竞争解释包含可控干预、区分观察和反证后的修正。特别是同值复制竞态由独立物理访问不变量判断，避免数值正确掩盖无序访问；CPU 模型与设备证据的边界声明清楚。",
      "evidence": [
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "两份复制写入完全相同的 ν 和数值，串行数值模型可能仍返回正确结果；独立物理访问不变量必须拒绝这条轨迹。"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "先固定输入、范围、内容版本、计时终点和并发，再改变能区分解释的条件。"
        }
      ]
    }
  },
  "findings": [
    {
      "id": "K-HW-013-A04",
      "criterion": "algorithm",
      "evidence": "RESTORE_RANGE 创建任务时规定“建立 WAIT 任务并原子发布到 pending，随后尝试 PHYSICAL_ADMIT”，失败后“冲突时任务保持 WAIT”；但再次遇到已有任务的分支仅为“若存在相同 key 的 WAIT/ACTIVE 任务：将 parent 加入订阅者，保存同一完成票据，不重复提交”。主循环没有遍历已有 WAIT 任务并重新尝试 PHYSICAL_ADMIT 的步骤，消费者又要求“所有可能写本次实际范围的 WAIT/ACTIVE 恢复任务均已结束”。“继续其保存的推进位置”没有明确 WAIT 任务应恢复到哪一步及由谁触发。脚本 expanded 正常案例通过 st.finish_read('old') 后显式 require(st.start_copy(move)) 推进，绕过了正文尚未给出的调度转换。",
      "impact": "正文自己的放大复制案例可以触发：old 正在读取有效的 D[0,2)，new 需要失效的 [2,4)，恢复策略创建写 [0,4) 的任务并因 old 的物理 R 进入 WAIT。old 完成后，冲突已经消失，但若按 RESTORE_RANGE 重新进入，已有 WAIT 分支只订阅，不再尝试启动；new 又等待该任务结束。没有其他在途工作时，主循环会拒绝本可合法完成的访问，或持续等待。当前测试的人工再次启动不能证明正文算法能够自行推进。",
      "blocking": true,
      "required_revision": "明确已有 WAIT 恢复任务的重试入口和 WAIT→ACTIVE 转换，例如每轮完成处理后，由同一状态拥有者对可重试 WAIT 任务重新核对版本、地址和保活，再原子调用 PHYSICAL_ADMIT，成功后只提交一次；或明确保存并恢复到该准入步骤的任务续执行机制。保持原 parent、uid 和订阅关系。让放大复制等待读者的检查通过这一实际推进入口在读者完成后自动排空，并加入遗漏重试的负对照；无需实现或穷尽完整 phase/DAG 调度器。"
    }
  ],
  "limitations": [
    "A03 的物理冲突安全性修复已复核关闭；本轮阻塞项是当前新增 WAIT 状态的推进转换。",
    "模型未覆盖完整 phase/DAG 调度、任意异步交错、取消、部分提交失败及多设备别名；正文已如实声明。这些边界本身不构成额外阻塞项。",
    "没有目标 GPU 的映射资格、真实可见性、链路事务、TLB、UVM 驻留、allocator、图重放或性能实测，也没有 Agent 使用效果证据。",
    "本次依据直接提供的文本、哈希和执行记录审阅；未独立重算文件哈希、检查离线链接目标存在性或重新运行最终 Python 脚本。当前工具未提供文件读取或 Python 执行能力。"
  ],
